# Part B: turbocharger speed chain (functions, state, calibration, DTCs).
from gen_W9_charge_turbo_a import *   # noqa: F401,F403  (ROWS, helpers, BOOT)

CHAIN = ("e2m block alignment (relative offsets, equal for every cell): state block 0x40afe6 = 0x0117C800, estimate block 0x40afc4 = 0x0118CB00, "
         "source / state block 0x40afd6 = 0x011A3500, calibration block 0x3ff6ec = 0x0117CA00, sensor / default pair 0x40bdc4 / 0x40bdc6 = 0x01196644 / 0x01196646.")

# ---------------------------------------------------------------- functions
fn("0x0050f4c0", "phase_group_b_updateBoostBlendingControl", "cm848_updateTurbochargerSpeedSensor",
   "Turbocharger speed sensor update (TPU-B channel 1 pulse train): with the sensor installed it counts the timeout timer down and turns the captured pulse period into turbocharger_speed_sensor_frequency (Hz, 0 once the timer has expired), then runs the frequency diagnostic, the signal mode selection, the sensor speed calculation and the rate-of-change diagnostic. With the sensor not installed (turbocharger_speed_sensor_installed = 0, as in the dump) it clears the three sensor fault bits (611 / 613 / 618), sets the frequency to 0, the sensor value to the global default and the signal mode to 0x100. (was phase_group_b_updateBoostBlendingControl)",
   "Code: reads the period latched by the TPU-B channel 1 interrupt (cm848_turbochargerSpeedSensorInterruptHandler) and computes pulses_per_interrupt x 312500 / (period x pulses_per_revolution); 312500 = TPU ticks per second (the 3.2 us tick of the vehicle speed sensor on TPU-B 2). " + CHAIN + " The calibration cell 0x3ff71a (e2m Turbo_Speed_Sensor_Installed, 'when 0 disables the turbo speed sensor processing') is 0 in the dump, matching the disabled branch (signal mode 0x100). Not on the Dodge pinout (docs/ecu_pinout.md lists no turbo speed sensor).")
fn("0x0050eeb0", "fuel_egrTarget_pressureRatio_calc", "cm848_diagnoseTurbochargerSpeedSensorFrequency",
   "Frequency diagnostic of the turbocharger speed sensor: the fault counter rises by the increment while the frequency is above the high limit (or below the low limit with the pressure ratio above its threshold and engine speed above the low-frequency threshold) and falls by the decrement inside the limits; at the set count it sets bit 3 (high, fault 611, P2581) or bit 5 (low, fault 613, P2580) of fault_detected_bits_608_to_623 and takes the global default as the speed target, below the clear count it clears them. (was fuel_egrTarget_pressureRatio_calc)",
   "Code: compares turbocharger_speed_sensor_frequency with 0x3ff6fe / 0x3ff700 (e2m Turbo_Speed_High_Error_Limit / Low_Error_Limit, HZ) and counts with 0x3ff6f6 / f4 / f8 / f2 (Turbo_Speed_Fault_Increment / Decrement / Set / Clear); its only fault outputs are bits 0x8 and 0x20 of the word at 0x3fe9c0, which is word 38 of the fault-detected array ((0x3fe9c0 - 0x3fe974) / 2). Fault 611 / 613 map through the ROM 0x5985a slot table to obd_dtc_code_table slots 59 / 69 = P2581 / P2580 (computed from the ROM image).")
fn("0x0050f110", "fuel_smokeLimit_modeSelect", "cm848_selectTurbochargerSpeedSensorSignalMode",
   "Signal mode of the turbocharger speed sensor: 2 while bit 3 or bit 5 of fault_detected_bits_608_to_623 is set (frequency fault), 1 while the sensor fault counter is non-zero, otherwise 0; forced to 0 while the calibrated sensor override is enabled. (was fuel_smokeLimit_modeSelect)",
   "Code: reads the two fault bits and the fault counter written by cm848_diagnoseTurbochargerSpeedSensorFrequency; mode 0x100 (sensor not installed) is set by cm848_updateTurbochargerSpeedSensor. Output feeds turbocharger_speed_in_range_state (e2m Turbo_Speed_IR_State).")
fn("0x0050f178", "governor_speedReference_ramp_calc", "cm848_calculateTurbochargerSpeedSensorValue",
   "Calculates the sensor turbocharger speed: the frequency goes through a two-point table to speed (turbocharger_speed_unfiltered, 8 rpm per count), a two-stage rising-rate limiter, a first-order filter and a peak hold over the last turbocharger_speed_envelope_filter_buffer_size values into turbocharger_speed_sensor_value, which is 0 below turbocharger_speed_zero_limit (except in signal mode 2), the calibrated override value while the sensor override is enabled and the previous value in signal mode 1. (was governor_speedReference_ramp_calc)",
   "Code: table at 0x40770e / 0x407714 (2 points, 0 Hz = 0 and 2500 Hz = 21425 in the dump), rate limiter cells 0x3ff714 / 0x3ff716 (e2m C_Turbo_Speed_Rate_Limit_Thd / _Value, 'rising rate limiter'), EMA coefficient 0x3ff6fa (Turbo_Speed_Filter_Constant), peak hold buffer size 0x3ff718 (C_Envelope_Filter_Buffer_Size), zero limit 0x3ff70c (Turbo_Speed_Zero_Limit: 'a Filtered_Turbo_Speed value below this limit is set to zero'). The intermediate words are e2m Unfiltered_Turbo_Speed / First_Stage_Output / Rate_Limited_Turbo_Speed / Filtered_Limited_Turbo_Speed / Filtered_Limited_Turbo_Speed_Max.")
fn("0x0050f3b4", "fuel_smokeLimit_transient_counter", "cm848_diagnoseTurbochargerSpeedSensorRateOfChange",
   "Rate-of-change (in-range) diagnostic of the turbocharger speed sensor: with no frequency fault and the pressure ratio above its threshold, turbocharger_speed_sensor_in_range_error_counter counts up when the speed step is above the maximum positive or below the maximum negative rate and down otherwise; at the count limit it sets bit 10 of fault_detected_bits_608_to_623 (fault 618, P2579), at 0 it clears it. (was fuel_smokeLimit_transient_counter)",
   "Code: counter limit 0x3ff6ec (e2m Turbo_Speed_Diag_Count_Limit, 'above this count number the in-range error flag is set', 20), rate limits 0x3ff702 (lha, signed -25000) / 0x3ff704 (15000) (Turbo_Speed_Max_Neg_Rate / Max_Pos_Rate). Fault 618 maps through the ROM slot table to slot 77 = P2579 (computed from the ROM).")
fn("0x0050ec8c", "governor_smoke_statusFlag_update", "cm848_updateTurbochargerSpeedInRangeState",
   "Builds turbocharger_speed_in_range_state (e2m Turbo_Speed_IR_State) from the sensor signal mode and bit 0x20 when the rate-of-change fault 618 (bit 10 of fault_detected_bits_608_to_623) is set. (was governor_smoke_statusFlag_update)",
   "Code: OR of fuel_smoke_limit_mode (0 / 1 / 2 / 0x100) with 0x20 when bit 0x400 of the word at 0x3fe9c0 is set; output at 0x40afe2 = e2m 0x011A350C (Turbo_Speed_IR_State).")
fn("0x0050ecc4", "fuel_demandSource_modeSelect", "cm848_selectTurbochargerSpeedSource",
   "Selects the turbocharger speed: turbocharger_speed_state is the calibrated override value while the user override trim is set, otherwise the estimation status | the in-range state | 0x200 (estimate test trim); the sensor value is used (turbocharger_speed_source 0) while the sensor signal is good (state bits 0x2 / 0x20 / 0x100 / 0x200 clear), the estimate (source 1) when the sensor is bad and the estimation status is 0, otherwise the global default value (source 2); also sets turbocharger_speed_sensor_disabled_flag (state bit 0x100). (was fuel_demandSource_modeSelect)",
   "Code (decoded from the nested tests): sensor value iff neither 0x2/0x20 (signal bad) nor 0x100/0x200 (disabled / estimate forced); estimate iff the sensor is bad and estimation status bits 0x40 / 0x80 are clear; default otherwise. Sources: governor_speed_reference_raw = sensor value 0x40bdc4, governor_temperature_correction = estimate 0x40afc4, egr_smoke_speed_demand_working = default 0x40bdc6 (e2m Turbo_Speed_Sensor / Turbo_Speed_Est / Turbo_Speed_Default). Dump: state 0x100, source 1, speed = the estimate (2086 = 16.7 KRPM). " + CHAIN)
fn("0x0050ee44", "phase_group_b_dispatchControlFunctions", "cm848_updateTurbochargerSpeedSelection",
   "Runs cm848_updateTurbochargerSpeedInRangeState and cm848_selectTurbochargerSpeedSource. (was phase_group_b_dispatchControlFunctions)",
   "Code: the body is exactly the two calls.")
fn("0x0050ee68", "cm848_initBoostControlModeAndFallback", "cm848_initializeTurbochargerSpeedSource",
   "Boot initialization of the turbocharger speed selection: turbocharger_speed_source is 0 (2 when the sensor signal mode is not 0), turbocharger_speed starts as the sensor value and turbocharger_speed_default_value as the calibrated global default. (was cm848_initBoostControlModeAndFallback)",
   "Code: writes boost_control_mode, fuel_demand_quantity and egr_smoke_speed_demand_working from fuel_smoke_limit_mode, governor_speed_reference_raw and egr_smoke_limit_default_speed_reference.")
fn("0x0050f680", "mpc555_tpuBChannel1InterruptHandler", "cm848_turbochargerSpeedSensorInterruptHandler",
   "TPU-B channel 1 interrupt of the turbocharger speed sensor (entry 1 of tpu_b_channel_interrupt_handler_table, reached through mpc555_tpuBInterruptDispatcher 0x55d2c, no direct caller): latches the captured period of turbocharger_speed_sensor_pulses_per_interrupt pulses into turbocharger_speed_sensor_pulse_period_working and reloads the timeout timer with turbocharger_speed_sensor_timeout. (was mpc555_tpuBChannel1InterruptHandler)",
   "Code: same pattern as cm848_vehicleSpeedSensorInterruptHandler (TPU-B 2) and the fan speed handler (TPU-B 9); consumer is cm848_updateTurbochargerSpeedSensor. Boot reload cell 0x3ff70a = e2m Turbo_Speed_Timeout (10 x 10 ms).")
fn("0x0050f6c4", "hpcr_configureTPUTimerInterrupts", "cm848_initializeTurbochargerSpeedSensorChannel",
   "Boot initialization of the turbocharger speed sensor input on TPU-B channel 1 (function 0xd, period measurement like the vehicle speed sensor on channel 2; priority 2, channel interrupt on): loads the pulses per interrupt, sets bit 1 of output_line_state.lines_48_to_55 (line 49 if bit 0 is line 48) from turbocharger_speed_sensor_configuration (1 = variable reluctance, 0 = eddy current sensor), clears the in-range fault bits and seeds the speed filter with turbocharger_speed. (was hpcr_configureTPUTimerInterrupts)",
   "Code: CFSR3 low byte field for channel 1 is set to 0xd, CPR1 / CIER / HSQR1 / HSRR1 touch channel 1 only; output_line_state.lines_48_to_55 bit 1 follows 0x3ff70e (not verified which line number that bit is) (e2m Turbo_Speed_Configuration '1 = VR, 0 = Eddy current'); 0x50f80c reads fuel_demand_quantity as the filter seed.")
fn("0x0002c764", "cm848_processProtectionEntry", "cm848_estimateTurbochargerSpeed",
   "Estimates the turbocharger speed (turbocharger_speed_estimate, 8 rpm per count): the boost lead term (gain x charge pressure change, first-order filtered) is added to a 3-D table of corrected turbine speed (charge pressure ratio x filtered engine speed) scaled by a temperature factor looked up on the ambient air temperature; also sets turbocharger_speed_estimation_status (0x80 when the estimation is disabled or an input state is 2, 0x40 when one is 1, else 0) and the difference from the sensor speed. (was cm848_processProtectionEntry)",
   "Code + e2m: gain 0x40729c = C_TSE_Boost_Lead_Gain (0x0118CC00), filters 0x40729e / 0x4072a0 = C_TSE_Boost_Lead_Filter_Constant / C_TSE_RPM_Filter_Constant, the 3-D table 0x4072a2-0x407308 (by role e2m C_TPE_3D_Turbo_Speed_Table 0x018D1A00 'turbo spd estimate table Z-axis'); results land at the e2m Turbo_Speed_Est block 0x0118CB00 (Turbo_Speed_Est, Turbo_Speed_EStat, TPE_Corrected_Turbo_Speed_Est, TSE_Boost_Lead_Term_Unfiltered / _Lead_Term, TSE_Filt_Engine_Spd, Turbo_Speed_Est_Delta, TSE_Filtered_Turbo_Speed) at equal offsets. CM550 candidate FUN_000254b6 is only a review-tier match (score 20), so no shared name is proposed.")
fn("0x0002c9bc", "mpc555_initFuelControlModeVariables", "cm848_initializeTurbochargerSpeedEstimate",
   "Boot initialization of the turbocharger speed estimate: clears the previous charge pressure sample and the engine speed filter accumulator, sets the two table interpolation states to 2 and points the boost lead filter at its constant. (was mpc555_initFuelControlModeVariables)",
   "Code: the body of the old function; the states it clears belong to cm848_estimateTurbochargerSpeed.")
fn("0x0050ec08", "cm848_updateThrottleRateFilterTimer", "cm848_updateTurbochargerOverspeedImmediateDerate",
   "Immediate overspeed derate timer: counts passes while turbocharger_speed is at or above turbocharger_overspeed_immediate_derate_speed_threshold (136 KRPM in the dump) and sets turbocharger_overspeed_immediate_derate_flag once the count reaches turbocharger_overspeed_immediate_derate_waiting_time; below the threshold it clears both. cm848_calculateChargeFlowTurbochargerSpeedDerate then forces the speed derate offset to 0. (was cm848_updateThrottleRateFilterTimer)",
   "Code + e2m: the two cells it compares with (0x407298 = 2, 0x40729a = 17000) are e2m AH_Fuel_Derate_Imm_Waiting_Time (0x01180500, SEC 0.05, 'waiting time in severe overspeed condition before derate') and TU_WG_Immediate_Speed_Derate_Thr (0x01180502, KRPM 0.008, 'turbo limit speed for immediate engine derate') at equal offsets. 17000 x 0.008 = 136 KRPM is above the derate limit 130 KRPM (16250).")
fn("0x0052d524", "cm848_completeBoostPressureMonitorReport", "cm848_completeBoostPressureMonitorReport",
   "Completion of the Boost / MAP monitor group 0: when faults 64 (P0236 boost pressure sensor range), 729 (P0299 underboost, mask 0x200 of fault_detected_bits_720_to_735) and 778 (P0069 MAP / barometric pressure correlation, mask 0x400 of fault_detected_bits_768_to_783) are unchanged against their previous-pass copies it sets bit 0 of diagnostic_monitor_complete_bits (and bit 20 when fault 778 is set) and clears the pending bits, gated on the group 21 ring triggers.",
   "Conflict resolved by decoding both sides (ROM slot table 0x5985a / obd_dtc_code_table 0x5b57c, and the detectors): the compared words are fault bits, and the detectors that set them are boost / MAP checks in cm848_calibration_group21_load (0x52d6a8): at cranking intake manifold pressure above DAT_000642be sets fault 64 (P0236), and a barometric - intake manifold pressure difference above DAT_000642cc sets fault 778 (P0069); at the governor setpoint with speed and load gates, boost above barometric below DAT_000642ca for more votes than DAT_000642c6 sets fault 729 (P0299 underboost). No EGR delta pressure is involved. The word diagnostic_status_flags_working at 0x3fe9d4 is word 48 of the fault-detected array (faults 768-783) and only mask 0x400 has a DTC (P0069); masks 0x40 / 0x80 / 0x100 / 0x200 (faults 774-777) have no DTC slot (internal). The EGR delta pressure plausibility function cm848_calibration_group22_load sets 0x240 there (faults 774 and 777, no DTC), which is why the group 21 / 22 context looked EGR related. The name stays right: P0236 / P0299 / P0069 are all boost / MAP DTCs. cm848_calibration_group21_load (not renamed here, read only in part) is the detector of this monitor.")

# ---------------------------------------------------------------- state words (existing rows)
g("0x0040afe6", "fuel_demand_quantity", "turbocharger_speed",
  "code: the selected turbocharger speed in KRPM x 0.008 (8 rpm per count), written by cm848_selectTurbochargerSpeedSource from the sensor value, the estimate or the global default; read by the charge flow turbocharger speed derate, the wastegate duty request (error = speed limit - speed), the compressor outlet temperature estimate (corrected speed), the charge pressure estimate (cm848_calculateBoostTorqueOffset, between the cal thresholds boost_control_fuel_lower / upper_threshold_cal = e2m C_Charge_Press_Turbo_Low / High_Thd), the EGR delta pressure autozero enable (C_EGR_AZ_Turbo_Speed_Thd 'max Filtered_Turbo_Speed'), governor_adjustment_compare (altitude threshold) and the overspeed immediate derate timer. e2m: Filtered_Turbo_Speed (0x0117C800, KRPM 0.008) is the block base. Dump 2086 = 16.7 KRPM (the estimate; the sensor is not installed). (was fuel_demand_quantity)")
g("0x0040afe8", "egr_fuel_pressure_ratio", "turbocharger_speed_sensor_frequency",
  "code: sensor pulse frequency in Hz = pulses per interrupt x 312500 / (captured period x pulses per revolution), 0 when the timeout timer has expired; input of the speed table and of the high / low frequency limits. e2m: Raw_Turbo_Speed (0x0117C802, HZ 'raw frequency input'). Dump 0. (was egr_fuel_pressure_ratio)")
g("0x0040afea", "egr_fuel_pressure_integrator", "turbocharger_speed_sensor_fault_counter",
  "code: frequency fault counter (up by the increment, down by the decrement, clamped at the set count); at the set count bit 3 / bit 5 of fault_detected_bits_608_to_623 is set, below the clear count it is cleared. e2m: Turbo_Speed_Fault_Count (0x0117C804). Dump 0. (was egr_fuel_pressure_integrator)")
ng("0x0040afec", "turbocharger_speed_sensor_period", "dword",
   "width: xref_addr.py says dword (0 reads / 2 writes: cm848_updateTurbochargerSpeedSensor, cm848_initializeTurbochargerSpeedSensorChannel). code: the captured period in 1/6553600 s = ticks x 0x640000 / 0x4c4b4; 0xffffffff at boot (dump: no pulse yet). e2m: Turbo_Speed_Period (0x0117C806, 4 bytes, SEC 1.52587890625E-7).")
g("0x0040aff0", "boost_blend_dwell_countdown", "turbocharger_speed_sensor_timeout_timer",
  "code: counts down by 1 per pass (10 ms) from turbocharger_speed_sensor_timeout, reloaded by the TPU-B channel 1 interrupt; at 0 the frequency is forced to 0. e2m: Turbo_Speed_Timer (0x0117C80A, MSEC 10). Dump 0. (was boost_blend_dwell_countdown)")
g("0x0040aff2", "governor_speed_ramp_target", "turbocharger_speed_unfiltered",
  "code: the speed table output before the rate limiters and the filter (the global default while a frequency fault is set). e2m: Unfiltered_Turbo_Speed (0x0117C80C, KRPM 0.008). Dump 0. (was governor_speed_ramp_target)")
g("0x0040aff4", "governor_speed_ramp_ema", "turbocharger_speed_filtered_limited",
  "code: first-order filter (turbocharger_speed_sensor_filter_constant) output after the two rate limiters. e2m: Filtered_Limited_Turbo_Speed (0x0117C80E, 'rate limited & filtered turbo speed'). Dump 0. (was governor_speed_ramp_ema)")
ng("0x0040aff6", "turbocharger_speed_rate_limited", "word",
   "width: xref_addr.py says word (0 reads / 1 write in cm848_calculateTurbochargerSpeedSensorValue). code: the output of the second rising-rate limiter stage, the input of the filter. e2m: Rate_Limited_Turbo_Speed (0x0117C810, KRPM 0.008).")
g("0x0040aff8", "smoke_limit_transient_counter", "turbocharger_speed_sensor_in_range_error_counter",
  "code: rate-of-change error counter of cm848_diagnoseTurbochargerSpeedSensorRateOfChange (limit turbocharger_speed_sensor_in_range_error_count_limit sets fault 618 / P2579). e2m: Turbo_Speed_Error_Counter (0x0117C812, 'error counter for In-Range failure'). Dump 0. (was smoke_limit_transient_counter)")
ng("0x0040affa", "turbocharger_speed_filtered_limited_maximum", "word",
   "width: xref_addr.py says word (0 reads / 1 write in cm848_calculateTurbochargerSpeedSensorValue). code: peak (envelope) of the last turbocharger_speed_envelope_filter_buffer_size filtered values; it is what turbocharger_speed_sensor_value takes. e2m: Filtered_Limited_Turbo_Speed_Max (0x0117C814, 'Turbo Speed sensor reading after two stage rate limiter').")
g("0x0040affc", "governor_speed_ramp_working", "turbocharger_speed_first_stage_rate_limited",
  "code: output of the first rising-rate limiter stage. e2m: First_Stage_Output (0x0117C816, KRPM 0.008). Dump 0. (was governor_speed_ramp_working)")
g("0x0040bdc4", "governor_speed_reference_raw", "turbocharger_speed_sensor_value",
  "code: the sensor turbocharger speed (peak held, zero limited), the first source of cm848_selectTurbochargerSpeedSource (source 0); the global default while the sensor is not installed. e2m: Turbo_Speed_Sensor (0x01196644, 'Turbo Speed sensor reading after Generic A/D block'); the generic sensor block base is 0x40bd80 = 0x01196600 (sensor_channel108_value 0x40bd94 is e2m EGR_Orifice_Tmptr_Sensor 0x01196614), so 0x40bdc4 is +0x44. Dump 16625 = 133 KRPM (the default). (was governor_speed_reference_raw)")
g("0x0040bdc6", "egr_smoke_speed_demand_working", "turbocharger_speed_default_value",
  "code: working copy of the calibrated global default turbocharger speed (copied at boot by cm848_initializeTurbochargerSpeedSource), the third source of cm848_selectTurbochargerSpeedSource (source 2). e2m: Turbo_Speed_Default (0x01196646). Dump 16625. (was egr_smoke_speed_demand_working)")
g("0x0040be36", "fuel_smoke_limit_mode", "turbocharger_speed_sensor_signal_mode",
  "code: signal mode of the speed sensor: 0 good, 1 frequency fault counter running, 2 frequency fault set (fault 611 / 613), 0x100 sensor not installed (in mode 1 the previous sensor value is held). Dump 0x100. (was fuel_smoke_limit_mode)")
g("0x0040afe2", "smoke_limit_mode_egr_status_combined", "turbocharger_speed_in_range_state",
  "code: signal mode | 0x20 while the rate-of-change fault 618 is set; ORed into turbocharger_speed_state. e2m: Turbo_Speed_IR_State (0x011A350C). Dump 0x100. (was smoke_limit_mode_egr_status_combined)")
ng("0x0040afe4", "turbocharger_speed_sensor_disabled_flag", "word",
   "width: xref_addr.py says word (0 reads / 1 write in cm848_selectTurbochargerSpeedSource). code: turbocharger_speed_state & 0x100 (sensor not installed or forced off). e2m: Turbo_Speed_Disabled (0x011A350E, 'when non-zero Turbo speed sensor is disabled'). Dump 0x100.")
g("0x0040afd6", "boost_control_mode", "turbocharger_speed_source",
  "code: which source turbocharger_speed is taken from: 0 sensor, 1 estimate, 2 global default; read by the charge flow turbocharger speed derate (backup limit while 1), the charge pressure estimate (0x80 status when 2, 0x40 when 1) and the compressor outlet temperature selection (state code 1 when 2). e2m: Turbo_Speed_Source (0x011A3500, 'Turbo Speed Sensor Source quality indicator'). Dump 1 (estimate). (was boost_control_mode)")
g("0x0040afd8", "fuel_demand_mode_flags_working", "turbocharger_speed_state",
  "code: source selection state: the calibrated override value (while the user override trim is set) or estimation status | in-range state | 0x200 (estimate test trim); bits 0x2 / 0x20 sensor signal bad, 0x40 / 0x80 estimate degraded / unavailable, 0x100 sensor disabled, 0x200 estimate forced. e2m: Turbo_Speed_State (0x011A3502). Dump 0x100. (was fuel_demand_mode_flags_working)")
# estimate block
g("0x0040afc4", "governor_temperature_correction", "turbocharger_speed_estimate",
  "code: estimated turbocharger speed (8 rpm per count): the scaled corrected-speed table output plus the boost lead term, the second source of cm848_selectTurbochargerSpeedSource (source 1). e2m: Turbo_Speed_Est (0x0118CB00, 'Estimation of turbo speed'). Dump 2086 = 16.7 KRPM. (was governor_temperature_correction)")
g("0x0040afc6", "governor_correction_mode_flags", "turbocharger_speed_estimation_status",
  "code: 0x80 when the estimation is disabled (bit 0 of algorithm_enable_flags_6_cal clear) or one of the four input state words is 2, 0x40 when one is 1, else 0; read by cm848_selectTurbochargerSpeedSource. e2m: Turbo_Speed_EStat (0x0118CB02, 'Turbo Speed Estimation Status'). Dump 0. (was governor_correction_mode_flags)")
g("0x0040afc8", "injection_timing_temp_correction_raw", "turbocharger_speed_estimate_corrected_speed",
  "code: output of the 3-D table (charge pressure ratio x filtered engine speed) before the temperature factor scaling. e2m: TPE_Corrected_Turbo_Speed_Est (0x0118CB04, 'estimated corrected turbo speed in rev/s/sqrt(degK)'). Dump 2096. (was injection_timing_temp_correction_raw)")
g("0x0040afcc", "governor_temp_correction_unfiltered", "turbocharger_speed_estimate_boost_lead_term_unfiltered",
  "code: boost_fuel_correction_gain_cal x 125 x (charge pressure - previous sample) / 12800, limited to +-25000. e2m: TSE_Boost_Lead_Term_Unfiltered (0x0118CB08, 'product of gain and boost press derivative before filter'). (was governor_temp_correction_unfiltered)")
g("0x0040afce", "governor_temp_correction_filtered", "turbocharger_speed_estimate_boost_lead_term",
  "code: the boost lead term after the first-order filter (constant 0x40729e); added to the estimate. e2m: TSE_Boost_Lead_Term (0x0118CB0A). (was governor_temp_correction_filtered)")
g("0x0040afd0", "engine_rpm_ema_filtered", "turbocharger_speed_estimate_engine_speed_filtered",
  "code: engine speed first-order filtered (constant 0x4072a0) as the table input of the speed estimate. e2m: TSE_Filt_Engine_Spd (0x0118CB0C, RPM 0.125). (was engine_rpm_ema_filtered)")
g("0x0040afd2", "governor_speed_temp_corrected", "turbocharger_speed_estimate_delta",
  "code: turbocharger_speed_sensor_value - turbocharger_speed_estimate. e2m: Turbo_Speed_Est_Delta (0x0118CB0E, 'Filtered_Turbo_Speed - Turbo_Speed_Est'). (was governor_speed_temp_corrected)")
g("0x0040afd4", "governor_speed_reference_uncorrected", "turbocharger_speed_estimate_sensor_snapshot",
  "code: copy of turbocharger_speed_sensor_value taken by the estimate. e2m: TSE_Filtered_Turbo_Speed (0x0118CB10, 'snapshot of Filtered_Turbo_Speed done in Turbo Speed Estimation'). Dump 16625. (was governor_speed_reference_uncorrected)")
# time-shared helper cells
g("0x003fcc00", "boost_blend_tpu_ch1_period_working", "turbocharger_speed_sensor_pulse_period_working",
  "code: period of turbocharger_speed_sensor_pulses_per_interrupt pulses in 3.2 us TPU ticks, latched by the TPU-B channel 1 interrupt and read by cm848_updateTurbochargerSpeedSensor. " + BOOT + " (was boost_blend_tpu_ch1_period_working)")
g("0x003fcc04", "governor_speed_ramp_target_prev", "turbocharger_speed_unfiltered_previous",
  "code: previous speed table output (held while a frequency fault is set); base of the first rate limiter stage. " + BOOT + " (was governor_speed_ramp_target_prev)")
